import React, { useCallback, useRef } from 'react';
import { Redirect, Tabs, router, usePathname } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { useSession } from '../../lib/session';
import { colors, dn, fonts } from '../../lib/theme';

const icon = (name: keyof typeof Ionicons.glyphMap, active: keyof typeof Ionicons.glyphMap) =>
  ({ color, focused }: { color: any; focused: boolean }) => <Ionicons name={focused ? active : name} size={dn(21, 20)} color={color} />;

// Events is the authenticated home. The anchor is the only initial route Expo Router
// honors (a <Tabs initialRouteName> prop is discarded). On native the layout module
// loads asynchronously, so the anchor is often missing the first time the navigator
// reads it. `index` still sorts first in that case and sends people to Events.
// Without either, the shortest child name (`me`) wins.
export const unstable_settings = { anchor: 'events' };

export default function TabsLayout() {
  const { userId, loading } = useSession();
  const path = usePathname();
  const pathRef = useRef(path);
  pathRef.current = path;
  // The tab stays selected on a nested screen, and the default press then does nothing.
  // Send that press back to Messages or the profile form.
  const popNested = useCallback((root: '/chat' | '/me') => (e: { preventDefault: () => void }) => {
    const current = pathRef.current;
    if (!current.startsWith(`${root}/`)) return;
    e.preventDefault();
    router.navigate(root);
  }, []);
  if (!loading && !userId) return <Redirect href="/sign-in" />;
  return (
    <Tabs backBehavior="initialRoute" screenOptions={{
      headerShown: false,
      sceneStyle: { backgroundColor: colors.paper },
      tabBarStyle: { backgroundColor: '#fff', borderTopColor: colors.line, ...(dn({ height: 60, paddingTop: 6 }, {})) },
      tabBarActiveTintColor: colors.navy, tabBarInactiveTintColor: colors.faint,
      tabBarLabelStyle: { fontFamily: fonts.sansMedium, fontSize: 11 },
      tabBarAllowFontScaling: false,
    }}>
      <Tabs.Screen name="events" options={{ title: 'Events', tabBarIcon: icon('calendar-outline', 'calendar') }} />
      <Tabs.Screen name="groups" options={{ title: 'Groups', tabBarIcon: icon('people-outline', 'people') }} />
      <Tabs.Screen name="chat" options={{ title: 'Chat', tabBarIcon: icon('chatbubbles-outline', 'chatbubbles') }} listeners={{ tabPress: popNested('/chat') }} />
      <Tabs.Screen name="me" options={{ title: 'Profile', tabBarLabel: 'Profile', tabBarIcon: icon('person-circle-outline', 'person-circle') }} listeners={{ tabPress: popNested('/me') }} />
      {/* Old People / Stats URLs redirect into Chat and Profile. href:null would send them to Events instead. */}
      <Tabs.Screen name="members" options={hiddenTab} />
      <Tabs.Screen name="analytics" options={hiddenTab} />
      {/* Keep the route. href:null would redirect /reports back to Events. */}
      <Tabs.Screen name="reports" options={hiddenTab} />
      <Tabs.Screen name="index" options={hiddenTab} />
    </Tabs>
  );
}

// Out of the tab bar, still reachable by URL and in-app links.
const hiddenTab = {
  tabBarButton: () => null,
  tabBarItemStyle: { display: 'none' as const, width: 0, maxWidth: 0, flexGrow: 0, flexBasis: 0, overflow: 'hidden' as const },
};
